SELECT * FROM (SELECT t.*, ROWNUM AS rowno FROM (SELECT h.id, h.fru_before fruBefore, h.fru_now fruNow, h.hardware_type hardwareType, h.fix_time fixTime, h.reason, h.description, h.create_time createTime, a.id assetId, a.name assetName, a.ip assetIp, a.ipmi_ip ipmiIp, a.asset_mode assetMode, g.name assetModeStr, b.name manufacturer, h.HARDWARE_TYPE hardwareType FROM ASSET_HARDWARE_FIX h LEFT JOIN ASSET a on a.ID = h.ASSET_ID LEFT JOIN ASSET_MODE g on a.desk = g.code LEFT JOIN ASSET_MANUFACTURER b on b.id = a.MANUFACTURER_ID WHERE 1 = 1
and a.name like concat(concat('%', #{assetName}), '%')
and h.hardware_type = #{hardwareType}
and a.desk = #{assetMode}
and to_char(h.fix_time, 'YYYY-MM') = #{month}
and h.asset_id in
NULL ) OR h.asset_id IN (#{id}
ORDER BY h.CREATE_TIME DESC) t WHERE ROWNUM < #{end}) tt WHERE tt.rowno > #{start}
